import os,re,numpy as np
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp=np.array(G['Demo pair 1 input']); out=np.array(G['Demo pair 1 output'])
H,W=inp.shape
diff=(inp!=out)
lab=np.zeros((H,W),int); n=0
for y in range(H):
    for x in range(W):
        if inp[y,x]==0 and lab[y,x]==0:
            n+=1; q=[(y,x)]; lab[y,x]=n
            while q:
                a,b=q.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=a+dy,b+dx
                    if 0<=ny<H and 0<=nx<W and inp[ny,nx]==0 and lab[ny,nx]==0:
                        lab[ny,nx]=n; q.append((ny,nx))
# Which comps' rings partially changed and where were the UNCHANGED ring cells located relative to other zeros?
from collections import Counter
cnt=Counter()
for i in range(1,n+1):
    ys,xs=np.where(lab==i)
    if len(ys)<2: continue
    r0,r1,c0,c1=int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max())
    ring={(y,x) for y in range(max(r0-1,0),min(r1+2,H)) for x in range(max(c0-1,0),min(c1+2,W))
          if y in (r0-1,r1+1) or x in (c0-1,c1+1)}
    unch=[p for p in ring if diff[p]]
    # unchanged ones: list with info
    unrec=[p for p in ring if not diff[p]]
    cnt[(i,len(unrec))]+=1
for i in range(2,n+1):
    ys,xs=np.where(lab==i)
    r0,r1,c0,c1=int(ys.min()),int(ys.max()),int(xs.min()),int(xs.max())
    ring={(y,x) for y in range(max(r0-1,0),min(r1+2,H)) for x in range(max(c0-1,0),min(c1+2,W))
          if y in (r0-1,r1+1) or x in (c0-1,c1+1)}
    if any(not diff[p] for p in ring):
        print('comp',i,(r0,r1,c0,c1),'unchanged:',[p for p in ring if not diff[p]])
